# ---------- audio ----------
SR=44100
tracks=[
 ('01-happy-playtime','Happy Playtime',392,[523.25,659.25,783.99,659.25]),
 ('02-calm-bedtime','Calm Bedtime',260,[261.63,329.63,392.00,329.63]),
 ('03-epic-adventure','Epic Adventure',330,[220.00,277.18,329.63,440.00]),
 ('04-bouncy-dance','Bouncy Dance',500,[329.63,392.00,493.88,587.33]),
 ('05-learning-focus','Learning Focus',300,[261.63,293.66,329.63,392.00]),
]
def tone(t, f, kind='sine'):
    x=2*np.pi*f*t
    if kind=='tri': return 2*np.abs(2*((f*t)%1)-1)-1
    return np.sin(x)
def synth(name, base, notes, seconds):
    n=int(SR*seconds); t=np.arange(n)/SR
    beat=60/base
    y=np.zeros(n,dtype=np.float32)
    for k,f in enumerate(notes):
        start=int(k*beat*0.5*SR); dur=int(beat*0.72*SR)
        end=min(n,start+dur)
        if start>=n: continue
        tt=np.arange(end-start)/SR
        env=np.minimum(tt*14,1)*np.minimum((dur/SR-tt)*10,1)
        y[start:end]+=0.22*np.sin(2*np.pi*f*tt)*env
        y[start:end]+=0.08*np.sin(2*np.pi*f*2*tt)*env
    # soft evolving pad and theme-specific pulse
    y += 0.06*np.sin(2*np.pi*(notes[0]/2)*t)*np.sin(np.pi*np.minimum(t,seconds-t)/max(seconds,1))
    pulse=(np.sin(2*np.pi*(base/60)*t)>0.78).astype(float)
    y += (0.025 if 'calm' not in name else 0.008)*pulse*np.sin(2*np.pi*notes[0]*2*t)
    y=np.tanh(y*1.7)
    fade=int(SR*0.03); y[:fade]*=np.linspace(0,1,fade); y[-fade:]*=np.linspace(1,0,fade)
    stereo=np.column_stack([y, np.roll(y, int(SR*0.002))])
    pcm=np.int16(np.clip(stereo,-1,1)*32767)
    wav=ROOT/'tunes'/f'{name}-{seconds}s.wav'
    with wave.open(str(wav),'wb') as w:
        w.setnchannels(2); w.setsampwidth(2); w.setframerate(SR); w.writeframes(pcm.tobytes())
    mp3=ROOT/'tunes'/f'{name}-{seconds}s.mp3'
    subprocess.run(['ffmpeg','-y','-loglevel','error','-i',str(wav),'-codec:a','libmp3lame','-b:a','128k',str(mp3)],check=True)
    wav.unlink()
for name,label,base,notes in tracks:
    for sec,suffix in [(60,'60s'),(30,'30s'),(20,'ringtone-20s')]:
        synth(name,base,notes,sec)

# ---------- transparent assets ----------
def save_png(img, path): img.save(ROOT/'assets'/path, 'PNG', optimize=True)
def canvas(): return Image.new('RGBA',(640,640),(0,0,0,0))
def star_points(cx,cy,r1,r2,n=5):
    pts=[]
    for i in range(n*2):
        a=-math.pi/2+i*math.pi/n; r=r1 if i%2==0 else r2
        pts.append((cx+math.cos(a)*r,cy+math.sin(a)*r))
    return pts
# note
im=canvas(); d=ImageDraw.Draw(im); d.ellipse((220,360,420,560),fill='#ff6b9d',outline='#fff8e7',width=12); d.rounded_rectangle((360,110,470,420),35,fill='#4fc3f7',outline='#fff8e7',width=12); d.ellipse((280,410,325,455),fill='#1a1730'); d.ellipse((365,410,410,455),fill='#1a1730'); d.arc((300,425,390,510),0,180,fill='#1a1730',width=12); save_png(im,'cute-music-note.png')
# sun
