for i in range(12):
 a=i*math.pi/6; d.line((cx+math.cos(a)*185,cy+math.sin(a)*185,cx+math.cos(a)*255,cy+math.sin(a)*255),fill='#ffd93d',width=28)
d.ellipse((105,105,535,535),fill='#ffd93d',outline='#fff8e7',width=14); d.ellipse((225,260,270,315),fill='#1a1730'); d.ellipse((370,260,415,315),fill='#1a1730'); d.arc((235,295,405,420),0,180,fill='#1a1730',width=14); save_png(im,'cute-sun.png')
# rainbow
