for i,c in enumerate(colors): d.arc((80+i*18,110+i*18,560-i*18,590-i*18),180,360,fill=c,width=34)
d.rectangle((80,350,560,590),fill=(0,0,0,0)); d.ellipse((240,410,280,455),fill='#1a1730'); d.ellipse((360,410,400,455),fill='#1a1730'); d.arc((255,420,385,505),0,180,fill='#1a1730',width=12); save_png(im,'cute-rainbow.png')
# simple animated assets
def frame(kind, idx, total=8):
 im=Image.new('RGBA',(240,240),(0,0,0,0)); d=ImageDraw.Draw(im); off=int(math.sin(idx/total*math.pi*2)*10)
 if kind=='note':
  d.ellipse((75,130+off,145,200+off),fill='#ff6b9d',outline='#fff8e7',width=5); d.rounded_rectangle((130,45+off,170,155+off),12,fill='#4fc3f7',outline='#fff8e7',width=5)
 elif kind=='star': d.polygon(star_points(120,120+off,74,34),fill='#ffd93d',outline='#fff8e7')
 else:
  d.ellipse((45,45+off,195,195+off),fill='#ffd93d',outline='#fff8e7',width=6)
  d.arc((85,105+off,155,160+off),0,180,fill='#1a1730',width=5)
 return im
for kind,fn in [('note','note-bounce'),('star','star-dance'),('sun','sun-wave')]:
 frames=[frame(kind,i) for i in range(8)]
 frames[0].save(ROOT/'assets'/f'{fn}.gif',save_all=True,append_images=frames[1:],duration=120,loop=0,disposal=2,transparency=0)
 frames[0].save(ROOT/'assets'/f'{fn}.apng',save_all=True,append_images=frames[1:],duration=120,loop=0,disposal=2)
# twinkle star APNG
frames=[frame('star',i,6) for i in range(6)]
frames[0].save(ROOT/'assets'/'star-twinkle.apng',save_all=True,append_images=frames[1:],duration=150,loop=0)
